<h1 class="h3 mb-3">站内通知</h1><?php if (!$notices): ?><div class="empty">暂无通知</div><?php else: foreach ($notices as $notice): ?><div class="card p-3 mb-2 <?=empty($notice['is_read']) ? 'border-primary' : ''?>"><div class="d-flex justify-content-between"><strong><?=h($notice['title'])?></strong><small class="text-muted"><?=fmt_time($notice['create_time'])?></small></div><div class="text-pre mt-2"><?=h($notice['content'])?></div><?php if (!$notice['is_read']): ?><form method="post" class="mt-2"><?=csrf_field()?><input type="hidden" name="id" value="<?=$notice['id']?>"><button class="btn btn-sm btn-outline-primary" formaction="<?=h(url_to('index/user/readNotice'))?>">标记已读</button></form><?php endif; ?></div><?php endforeach; endif; ?>
